"use strict";

const vm = require("vm");
const http = require("http");
const https = require("https");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const PAGE_HEADERS = {
  "user-agent": UA,
  accept:
    "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
  "accept-language": "en-US,en;q=0.9",
  "accept-encoding": "identity",
  "sec-ch-ua": '"Chromium";v="126", "Google Chrome";v="126", "Not;A=Brand";v="24"',
  "sec-ch-ua-mobile": "?0",
  "sec-ch-ua-platform": '"Windows"',
  "sec-fetch-dest": "document",
  "sec-fetch-mode": "navigate",
  "sec-fetch-site": "none",
  "upgrade-insecure-requests": "1",
};

const cleanUrl = (u) =>
  u ? String(u).replace(/\\u002F/g, "/").replace(/\\/g, "").replace(/&amp;/g, "&") : null;

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorb(headers) {
    const lines = headers && headers["set-cookie"];
    if (!Array.isArray(lines)) return;
    for (const line of lines) {
      const pair = String(line).split(";")[0];
      const i = pair.indexOf("=");
      if (i > 0) this.map.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim());
    }
  }
  toString() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
}

function requestOnce(urlStr, jar) {
  return new Promise((resolve, reject) => {
    let parsed;
    try {
      parsed = new URL(urlStr);
    } catch {
      reject(new Error("Invalid URL: " + urlStr));
      return;
    }
    const lib = parsed.protocol === "http:" ? http : https;
    const req = lib.request(
      parsed,
      {
        method: "GET",
        headers: { ...PAGE_HEADERS, cookie: jar.toString() },
        timeout: 25000,
      },
      (res) => {
        jar.absorb(res.headers);
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () =>
          resolve({
            status: res.statusCode || 0,
            headers: res.headers,
            body: Buffer.concat(chunks).toString("utf8"),
          })
        );
        res.on("error", reject);
      }
    );
    req.on("timeout", () => req.destroy(new Error("Request timed out")));
    req.on("error", reject);
    req.end();
  });
}

async function requestFollowingRedirects(url, jar, maxRedirects = 8) {
  let current = url;
  for (let i = 0; i <= maxRedirects; i++) {
    const res = await requestOnce(current, jar);
    const location = res.headers && res.headers.location;
    if (
      res.status >= 300 &&
      res.status < 400 &&
      location &&
      i < maxRedirects
    ) {
      current = new URL(location, current).toString();
      continue;
    }
    return { html: res.body, finalUrl: current };
  }
  return { html: "", finalUrl: current };
}

async function fetchPage(url, jar, hasData, attempts = 4) {
  let last = { html: "", finalUrl: url };
  for (let i = 0; i < attempts; i++) {
    try {
      last = await requestFollowingRedirects(url, jar);
      if (hasData(last.html)) return last;
    } catch {

    }
    await new Promise((r) => setTimeout(r, 700));
  }
  return last;
}

function parseNuxt(html) {
  const start = html.indexOf("window.__NUXT__=");
  if (start < 0) return null;
  const end = html.indexOf("</script>", start);
  if (end < 0) return null;
  const code = html.slice(start, end);
  const sandbox = { window: {} };
  vm.createContext(sandbox);
  try {
    vm.runInContext(code, sandbox, { timeout: 5000 });
  } catch {
    return null;
  }
  return sandbox.window.__NUXT__ || null;
}

function collectPhotos(nuxt) {
  const out = [];
  const seen = new Set();
  const push = (p) => {
    if (
      p &&
      typeof p === "object" &&
      p.photo_id_str &&
      Array.isArray(p.main_mv_urls) &&
      !seen.has(p.photo_id_str)
    ) {
      seen.add(p.photo_id_str);
      out.push(p);
    }
  };
  for (const entry of (nuxt && nuxt.data) || []) {
    if (!entry || typeof entry !== "object") continue;
    if (Array.isArray(entry.photoList)) entry.photoList.forEach(push);
    if (entry.feedsData && Array.isArray(entry.feedsData.feeds)) {
      entry.feedsData.feeds.forEach(push);
    }
  }
  return out;
}

const NAMED_ENTITIES = {
  amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ",
  aacute: "á", eacute: "é", iacute: "í", oacute: "ó", uacute: "ú",
  Aacute: "Á", Eacute: "É", Iacute: "Í", Oacute: "Ó", Uacute: "Ú",
  agrave: "à", egrave: "è", igrave: "ì", ograve: "ò", ugrave: "ù",
  atilde: "ã", otilde: "õ", Atilde: "Ã", Otilde: "Õ",
  acirc: "â", ecirc: "ê", ocirc: "ô", Acirc: "Â", Ecirc: "Ê", Ocirc: "Ô",
  ccedil: "ç", Ccedil: "Ç", ntilde: "ñ", Ntilde: "Ñ",
  auml: "ä", euml: "ë", iuml: "ï", ouml: "ö", uuml: "ü",
};

function decodeEntities(s) {
  return String(s || "")
    .replace(/&#x([0-9a-fA-F]+);/g, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&([A-Za-z]+);/g, (m, name) =>
      Object.prototype.hasOwnProperty.call(NAMED_ENTITIES, name)
        ? NAMED_ENTITIES[name]
        : m
    );
}

function firstUrl(list) {
  if (!Array.isArray(list)) return null;
  for (const item of list) {
    if (item && typeof item.url === "string" && item.url) return item.url;
  }
  return null;
}

function shapePhoto(photo) {
  const videoUrls = [];
  const seen = new Set();
  for (const item of photo.main_mv_urls || []) {
    if (item && item.url && !seen.has(item.url)) {
      seen.add(item.url);
      videoUrls.push(item.url);
    }
  }

  const cover =
    firstUrl(photo.cover_thumbnail_urls) || firstUrl(photo.cover_first_frame_urls);

  let musicUrl = null;
  if (photo.music && typeof photo.music === "object") {
    musicUrl = photo.music.url || firstUrl(photo.music.audioUrls);
  }

  return {
    caption: decodeEntities(photo.caption || ""),
    authorName: photo.user_name || null,
    authorUsername: photo.kwai_id || null,
    cover,
    video: videoUrls.length ? videoUrls[0] : null,
    musicUrl,
  };
}

function resolveInput(input) {
  const s = String(input || "").trim();
  if (!s) throw new Error("Invalid Kwai video URL or ID");
  const atVideo = s.match(/kwai\.com\/@([^/?#]+)\/video\/(\d{10,})/i);
  if (atVideo) {
    return {
      id: atVideo[2],
      url: `https://www.kwai.com/@${atVideo[1]}/video/${atVideo[2]}`,
    };
  }
  const plain =
    s.match(/kwai\.com\/video\/(\d{10,})/i) ||
    s.match(/kuaishou\.com\/short-video\/([A-Za-z0-9_-]+)/i) ||
    s.match(/kuaishou\.com\/f\/([A-Za-z0-9_-]+)/i);
  if (plain) return { id: plain[1], url: `https://www.kwai.com/video/${plain[1]}` };
  if (/^\d{10,}$/.test(s)) return { id: s, url: `https://www.kwai.com/video/${s}` };
  if (/^https?:\/\//i.test(s) && /(kwai\.com|kuaishou\.com)/i.test(s)) {
    const idMatch = s.match(/video\/(\d{10,})/i);
    return { id: idMatch ? idMatch[1] : null, url: s };
  }
  throw new Error("Invalid Kwai video URL or ID");
}

function idFromUrl(url) {
  const m = String(url || "").match(/video\/(\d{10,})/i);
  return m ? m[1] : null;
}

module.exports = async function fetchSelf(url) {
  const target = resolveInput(url);
  const jar = new Jar();
  const page = await fetchPage(target.url, jar, (h) => {
    const photos = collectPhotos(parseNuxt(h));
    if (!photos.length) return false;
    return !target.id || photos.some((p) => String(p.photo_id_str) === String(target.id));
  });
  const nuxt = parseNuxt(page.html);
  const photos = collectPhotos(nuxt);
  const finalId = target.id || idFromUrl(page.finalUrl);
  const photo =
    photos.find((p) => finalId && String(p.photo_id_str) === String(finalId)) ||
    photos[0];
  if (!photo) {
    throw new Error(
      "Could not extract this Kwai video — it may be deleted or private, or Kwai changed its page format"
    );
  }

  const shaped = shapePhoto(photo);
  const video = cleanUrl(shaped.video);
  if (!video) throw new Error("Kwai video not found (self-scrape)");

  return {
    success: true,
    source: "Kwai",
    data: {
      title: shaped.caption || "Kwai Video",
      author: shaped.authorName || shaped.authorUsername || "Unknown",
      thumbnail: cleanUrl(shaped.cover) || null,
      download: {
        video,
        audio: cleanUrl(shaped.musicUrl) || null,
        photo: null,
      },
    },
  };
};
